contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 role, address account) public {
        require(role != bytes32(0), "DEFAULT_ADMIN_ROLE is always admin for any role unless changed");
        require(account != address(0), "account is not zero address");

        // Make sure this test can act as the admin of `role`.
        // The deployer (this contract) initially has TIMELOCK_ADMIN_ROLE, which is the admin
        // for PROPOSER_ROLE and EXECUTOR_ROLE but not necessarily for arbitrary `role`.
        // Ensure this contract is admin: its own DEFAULT_ADMIN_ROLE admin is itself.
        // Grant this contract the admin role for `role` if needed; DEFAULT_ADMIN_ROLE
        // can call grantRole for any role whose admin is DEFAULT_ADMIN_ROLE.
        // However, role's admin may not be DEFAULT_ADMIN_ROLE. To avoid relying on that,
        // use roles whose admin is known to be this contract:
        // PROPOSER_ROLE admin is TIMELOCK_ADMIN_ROLE and this contract has TIMELOCK_ADMIN_ROLE.
        // EXECUTOR_ROLE admin is TIMELOCK_ADMIN_ROLE and this contract has TIMELOCK_ADMIN_ROLE.
        // So if `role` is PROPOSER_ROLE or EXECUTOR_ROLE, this contract can grant it directly.
        // Otherwise, skip granting and just check the invariant after a no-op? No, must have
        // meaningful call. Force role to be one of the manageable roles? But input is arbitrary bytes32.
        // Better: grant the role's admin to this contract, then grant the role, then check.
        // But granting role's admin may require calling grantRole for that admin role first.
        // For general role, we can set up by first ensuring this contract has the admin role of `role`
        // only if its admin is DEFAULT_ADMIN_ROLE (which this contract administers).
        // To make the test always feasible, we pre-grant `role` directly by first granting
        // the role's admin to this contract... that requires the admin be manageable.
        // The only reliably manageable admin is TIMELOCK_ADMIN_ROLE (self-administered and held by this contract).
        // So restrict to roles whose admin is TIMELOCK_ADMIN_ROLE or DEFAULT_ADMIN_ROLE with this contract as admin of that.
        // Given constraints and to keep it general but valid, we grant TIMELOCK_ADMIN_ROLE to this contract
        // (already done), then grant role` if its admin is TIMELOCK_ADMIN_ROLE. Otherwise, we cannot.
        // To make a meaningful, always-succeeding test, we set the role as PROPOSER_ROLE or EXECUTOR_ROLE?
        // But test is parameterized. We can use `role` directly if we first make this contract the admin.
        // The only universal way: use _setRoleAdmin is internal, not accessible. So we must work with
        // existing admins.
        // However, the property we want to test is simple: after a successful grantRole(role, account),
        // hasRole(role, account) is true. To guarantee the grantRole succeeds, the caller must have
        // the admin role of `role`. The caller is this contract. So we need getRoleAdmin(role) to be a role
        // this contract has.
        // This contract initially has TIMELOCK_ADMIN_ROLE (admin of TIMELOCK_ADMIN_ROLE, PROPOSER_ROLE, EXECUTOR_ROLE).
        // So we can grant PROPOSER_ROLE and EXECUTOR_ROLE and TIMELOCK_ADMIN_ROLE.
        // For arbitrary role, we cannot guarantee admin. So restrict role to PROPOSER_ROLE or EXECUTOR_ROLE?
        // But property should be general. The general rule is: if grantRole succeeds, hasRole becomes true.
        // We can test that by attempting grantRole and checking the result conditionally on success.
        // But we must end with exactly one assert. We can assert: if grantRole did not revert, then hasRole is true.
        // We cannot capture revert of grantRole directly without try/catch, but we can check state after.
        // Actually, if grantRole reverts, the whole tx reverts, so we cannot observe it unless we use try/catch.
        // But the template allows try/catch to capture revert booleans. Let's do that.
        // We'll try to grant role to account. If it succeeds, hasRole must be true.
        // If it reverts, no state change. The assert can be: grantRoleSucceeded => hasRole(role, account).
        // But we also need that the account was not already having the role before? Not necessary.
        // Let's implement with try/catch.

        bool succeeded;
        try c.grantRole(role, account) {
            succeeded = true;
        } catch {
            succeeded = false;
        }

        // If the grant succeeded, the account must now have the role.
        // Also, if it failed, the account may or may not have the role? It could already have it.
        // The general rule: after a successful grantRole, hasRole must be true.
        // This is a property that should hold for any role/account pair for which grantRole succeeds.
        bool has = c.hasRole(role, account);
        assert(!succeeded || has);
    }
}

