contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public {
        require(delay >= c.getMinDelay(), "delay too small");

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        c.grantRole(c.PROPOSER_ROLE(), address(this));
        c.schedule(target, value, data, predecessor, salt, delay);

        bool scheduled = c.isOperation(id);
        uint256 tsBefore = c.getTimestamp(id);
        bool reverted;
        try c.cancel(id) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 tsAfter = c.getTimestamp(id);
        bool operationAfter = c.isOperation(id);
        bool pendingAfter = c.isOperationPending(id);

        assert(scheduled && !reverted && tsBefore > 0 && tsAfter == 0 && !operationAfter && !pendingAfter);
    }

    receive() external payable {}
}

