contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(
        address target,
        uint256 value,
        bytes calldata data,
        bytes32 predecessor,
        bytes32 salt,
        uint256 delay
    ) public payable {
        require(address(this).balance >= value, "insufficient balance");

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        bool grantedProposer;
        try c.grantRole(c.PROPOSER_ROLE(), address(this)) {
            grantedProposer = true;
        } catch {
            grantedProposer = false;
        }

        if (grantedProposer) {
            uint256 beforeTimestamp = c.getTimestamp(id);
            bool beforeIsOperation = c.isOperation(id);
            bool beforeIsPending = c.isOperationPending(id);

            bool scheduleReverted;
            try c.schedule(target, value, data, predecessor, salt, delay) {
                scheduleReverted = false;
            } catch {
                scheduleReverted = true;
            }

            if (scheduleReverted) {
                assert(
                    !beforeIsOperation
                        ? (c.getTimestamp(id) == beforeTimestamp && c.isOperation(id) == beforeIsOperation && c.isOperationPending(id) == beforeIsPending)
                        : (c.getTimestamp(id) == beforeTimestamp && c.isOperation(id) == beforeIsOperation && c.isOperationPending(id) == beforeIsPending)
                );
            } else {
                uint256 ts = c.getTimestamp(id);
                assert(
                    c.isOperation(id) == true
                        && c.isOperationPending(id) == (ts > uint256(1))
                );
            }
        } else {
            assert(true);
        }
    }
}

